python
def ribbonRunsPositiveProofStrip(line, k):
    a=line
    out=[]
    i=0
    while i<len(a):
        j=i+1
        while j<len(a) and a[j]==a[i]: j+=1
        out.append(j-i)
        i=j
    return [x for x in out if x>0]


java
class Solution {
  public int[] ribbonRunsPositiveProofStrip(String line, int k) {
    String a=line; List<Integer> out=new ArrayList<>();
    {for(int i=0;i<a.length();){int j=i+1;while(j<a.length()&&a.charAt(j)==a.charAt(i))j++;out.add(j-i);i=j;}}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
